contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public test: takes one dummy parameter to vary inputs (required).
    // We will call refund() exactly once and assert that if it did not revert then
    // the caller's increase in Ether equals the contract's decrease in Ether.
    function run(uint256 dummy) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(true);

        // Record balances before the call
        uint256 beforeC = address(c).balance;
        uint256 beforeMe = address(this).balance;

        // Call refund and capture whether it reverted
        bool refundedReverted;
        c.refund(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            refundedReverted = true;
        } else {
            refundedReverted = false;
        }

        // Record balances after the call
        uint256 afterC = address(c).balance;
        uint256 afterMe = address(this).balance;

        // General rule: if refund succeeded then the amount this contract gained equals the amount c lost.
        // Expressed as: not reverted => (afterMe - beforeMe) == (beforeC - afterC)
        // Use guarded arithmetic to avoid underflow in the assert expression itself.
        assert(
            refundedReverted
            || (afterMe >= beforeMe && beforeC >= afterC && (afterMe - beforeMe) == (beforeC - afterC))
        );
    }

    receive() external payable { }
}

